/** Série en cours */
function StreakCard({ streak }) {
  const days = ["L","M","M","J","V","S","D"];
  const today = new Date().getDay();
  const todayIdx = today === 0 ? 6 : today - 1;

  return (
    <div style={{
      margin: "0 16px 16px",
      background: C.s1,
      borderRadius: 22,
      padding: "18px 18px",
      boxShadow: "0 3px 14px rgba(20,20,50,0.05)",
      position: "relative",
      overflow: "hidden",
    }}>
      <div style={{
        position: "absolute", top: -34, right: -30,
        width: 170, height: 170, borderRadius: "50%",
        background: "radial-gradient(circle,rgba(249,115,22,0.15),rgba(249,115,22,0) 70%)",
        pointerEvents: "none",
      }} />
      {/* Header */}
      <div style={{
        position: "relative",
        display: "flex", alignItems: "center", justifyContent: "space-between",
        marginBottom: 18,
      }}>
        <span style={{ fontSize: 14, fontWeight: 800, letterSpacing: "0.8px", fontFamily: FONT, color: C.text }}>
          SÉRIE EN COURS
        </span>
        <span style={{
          display: "flex", alignItems: "center", gap: 5,
          background: "#fff3e0", color: "#d97706",
          fontSize: 11.5, fontWeight: 800,
          padding: "5px 10px", borderRadius: 20, fontFamily: FONT,
        }}>
          ⭐ Record {streak > 0 ? streak * 2 : 18} j
        </span>
      </div>
      {/* Chiffre */}
      <div style={{
        position: "relative",
        display: "flex", alignItems: "center", gap: 14, marginBottom: 20,
      }}>
        <div style={{
          width: 54, height: 54, flexShrink: 0,
          borderRadius: 16,
          background: "linear-gradient(160deg,#fbbf24,#f97316)",
          display: "flex", alignItems: "center", justifyContent: "center",
          boxShadow: "0 8px 18px rgba(249,115,22,0.4)",
        }}>
          <span style={{ fontSize: 27 }}>🔥</span>
        </div>
        <div>
          <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
            <span style={{ fontSize: 42, fontWeight: 800, letterSpacing: "-2px", lineHeight: 1, color: "#f97316", fontFamily: FONT, ...NUM }}>
              {streak}
            </span>
            <span style={{ fontSize: 14, fontWeight: 800, color: C.text, fontFamily: FONT }}>jours</span>
          </div>
          <div style={{ fontSize: 13, color: C.dim, fontWeight: 700, marginTop: 1, fontFamily: FONT }}>
            consécutifs · continue !
          </div>
        </div>
      </div>
      {/* Semaine L→D */}
      <div style={{ display: "flex", justifyContent: "space-between", textAlign: "center" }}>
        {days.map((d, i) => {
          const isDone = i < Math.min(streak, 7);
          const isToday = i === todayIdx;
          return (
            <div key={i}>
              <div style={{
                width: 33, height: 33, margin: "0 auto",
                borderRadius: 11,
                background: isDone
                  ? "linear-gradient(160deg,#fbbf24,#f97316)"
                  : isToday ? "transparent" : "#f0f2f7",
                border: isToday ? "2px solid #f97316" : "none",
                display: "flex", alignItems: "center", justifyContent: "center",
                boxShadow: isDone ? "0 5px 11px rgba(249,115,22,0.32)" : "none",
              }}>
                {isDone ? (
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M5 12l5 5L20 6"/>
                  </svg>
                ) : isToday ? (
                  <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#f97316", display: "block" }} />
                ) : null}
              </div>
              <div style={{ fontSize: 12, fontWeight: 700, color: C.dim, marginTop: 6, fontFamily: FONT }}>{d}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

